-- Audit only: DO NOT change the ledger ID generation.
-- Verified on isolated Neon branch on 2026-11-02:
-- footy_cutover.points_ledger.id is GENERATED BY DEFAULT AS IDENTITY.
-- information_schema.columns.column_default is NULL for identity columns,
-- which does NOT mean an automatic generator is missing.
-- The earlier proposed CREATE SEQUENCE / ALTER COLUMN fix was incorrect.
-- Existing finish_new_match INSERT may omit id; PostgreSQL identity generates it.
SELECT column_name, is_identity, identity_generation, column_default
FROM information_schema.columns
WHERE table_schema='footy_cutover'
  AND table_name='points_ledger' AND column_name='id';
